package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.persistence.mapper.AgentPublicationMapper;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import java.util.*;import java.math.BigInteger;import java.time.LocalDateTime;
/** One-way disable with an immutable independent original request journal. Re-enabling requires a new release. */
public final class FormalAgentPublicationLifecycle {
 private final JdbcTemplate db;private final AgentPublicationJournal journal;private final AgentPublicationMapper versions;private final ResourceReadAuthority resources;private final FormalAgentPublicationSchema schema;private final PermissionSchema json;
 public FormalAgentPublicationLifecycle(DataSource data,AgentPublicationJournal journal,AgentPublicationMapper versions,ResourceReadAuthority resources,FormalAgentPublicationSchema schema,PermissionSchema json){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.journal=journal;this.versions=versions;this.resources=resources;this.schema=schema;this.json=json;}
 record Disabled(String project,String decision,String hash,String creator,LocalDateTime created,String schemaVersion,String schemaManifest,String classification){}
 private List<Disabled> disabled(EnterpriseAccess.Admission a,String release){return db.query("SELECT project_id,decision_id,decision_sha256,created_by,created_at,schema_version,schema_manifest_sha256,classification FROM formal_agent_publication_disable WHERE tenant_id=? AND release_id=? LIMIT 2",(r,n)->new Disabled(r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getTimestamp(5).toLocalDateTime(),r.getString(6),r.getString(7),r.getString(8)),a.context().tenant_id(),release);}
 void requireState(EnterpriseAccess.Admission a,FormalAgentPublicationObjectLedger.Row intent,JsonNode registration)throws Exception{
  var rows=db.query("SELECT status,revision,evaluation_id,updated_at FROM agent_version WHERE tenant_id=? AND project_id <=> ? AND agent_version_id=? AND content_sha256=? LIMIT 2 FOR UPDATE",(r,n)->new State(r.getString(1),r.getBigDecimal(2).toBigIntegerExact(),r.getString(3),r.getTimestamp(4).toLocalDateTime()),intent.tenant(),intent.project(),intent.candidate(),intent.candidateHash());var state=one(rows);var expected=new BigInteger(intent.expectedRevision()).add(BigInteger.ONE);var published=LocalDateTime.parse(registration.required("created_at").asText());String evaluation=schema.read(intent.payload()).required("evaluation_id").asText();if(!evaluation.equals(state.evaluation()))bad();var disabled=disabled(a,intent.release());String scopeStatus;BigInteger scopeRevision;LocalDateTime changed;
  if(disabled.isEmpty()){if(!"PUBLISHED".equals(state.status())||!expected.equals(state.revision())||!published.equals(state.changed()))bad();scopeStatus="ACTIVE";scopeRevision=BigInteger.ONE;changed=published;}
  else{var stored=one(disabled);var original=journal.read(a,stored.decision());var request=schema.validate("Disable",schema.read(original.requestJson()));var content=schema.read(original.contentJson());AgentPublicationWitness.requireGovernance(original,schema.read(original.authorizationsJson()),"agent.publish","AGENT_PUBLICATION",json);
   if(!Objects.equals(stored.project(),intent.project())||!stored.classification().equals(original.classification())||!"PUBLICATION".equals(original.kind())||!intent.release().equals(original.resourceId())||!stored.hash().equals(original.contentSha256())||!stored.creator().equals(original.createdBy())||!stored.created().equals(original.createdAt())||!stored.classification().equals(intent.classification())||!Objects.equals(original.projectId(),intent.project())||!"1.0.0".equals(stored.schemaVersion())||!schema.manifest().equals(stored.schemaManifest())||stored.created().isBefore(published))bad();
   if(!content.isObject()||content.size()!=7||!"1.0.0".equals(content.path("schema_version").asText())||!"DISABLED".equals(content.path("status").asText())||!intent.release().equals(content.path("release_id").asText())||!schema.hash(registration).equals(content.path("registration_sha256").asText())||!expected.toString().equals(content.path("expected_revision").asText())||!expected.add(BigInteger.ONE).toString().equals(content.path("resulting_revision").asText())||!schema.canonical(registration.required("scope_revisions")).equals(schema.canonical(content.required("scope_revisions")))||!intent.release().equals(request.path("release_id").asText())||!expected.toString().equals(request.path("expected_revision").asText()))bad();
   if(!"DISABLED".equals(state.status())||!expected.add(BigInteger.ONE).equals(state.revision())||!stored.created().equals(state.changed()))bad();scopeStatus="DISABLED";scopeRevision=BigInteger.TWO;changed=stored.created();
  }
  for(var scope:registration.required("scope_revisions")){String id=scope.required("scope_revision").asText();var count=one(db.query("SELECT COUNT(*) FROM release_scope WHERE tenant_id=? AND scope_revision=? AND release_id=? AND status=? AND revision=? AND updated_at=?",(r,n)->r.getInt(1),intent.tenant(),id,intent.release(),scopeStatus,scopeRevision,changed));if(count!=1)bad();}
 }
 JsonNode disable(EnterpriseAccess.Admission a,String key,JsonNode request,FormalAgentPublicationObjectLedger.Row intent,JsonNode registration)throws Exception{
  schema.validate("Disable",request);if(!intent.release().equals(request.path("release_id").asText()))bad();var previous=journal.prior(a,"PUBLICATION",key,request);if(previous!=null){requireState(a,intent,registration);return schema.read(previous.receiptJson());}requireState(a,intent,registration);if(!disabled(a,intent.release()).isEmpty())throw new TenantAccessException(ErrorCode.ACTION_STALE);var expected=new BigInteger(intent.expectedRevision()).add(BigInteger.ONE);if(!expected.toString().equals(request.path("expected_revision").asText()))throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);
  var grant=resources.require(a,FormalAgentCandidateService.governance(a,intent.project()),"agent.publish","AGENT_PUBLICATION");var v=journal.values(a);var now=(LocalDateTime)v.get("now");var content=json.object().put("schema_version","1.0.0").put("status","DISABLED").put("release_id",intent.release()).put("registration_sha256",schema.hash(registration)).put("expected_revision",expected.toString()).put("resulting_revision",expected.add(BigInteger.ONE).toString());content.set("scope_revisions",registration.required("scope_revisions").deepCopy());String id=UUID.randomUUID().toString(),hash=schema.hash(content);v.put("projectId",intent.project());v.put("versionId",id);v.put("entityKind","AGENT_PUBLICATION_RECORD");v.put("contentHash",hash);one(versions.insertVersion(v));var auth=json.object().put("identity_mode",a.bindingView().mode());auth.set("governance",AgentPublicationWitness.tree(grant));var saved=journal.save(a,intent.project(),id,"PUBLICATION",intent.release(),key,request,content,auth,intent.classification(),now);
  one(db.update("INSERT INTO formal_agent_publication_disable(tenant_id,project_id,release_id,decision_id,decision_sha256,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,?,'1.0.0',?,?,?,?)",intent.tenant(),intent.project(),intent.release(),id,hash,schema.manifest(),a.actorId(),now,intent.classification()));
  one(db.update("UPDATE agent_version SET status='DISABLED',revision=revision+1,updated_at=? WHERE tenant_id=? AND project_id <=> ? AND agent_version_id=? AND content_sha256=? AND status='PUBLISHED' AND revision=?",now,intent.tenant(),intent.project(),intent.candidate(),intent.candidateHash(),expected));
  for(var scope:registration.required("scope_revisions"))one(db.update("UPDATE release_scope SET status='DISABLED',revision=2,updated_at=? WHERE tenant_id=? AND scope_revision=? AND release_id=? AND status='ACTIVE' AND revision=1",now,intent.tenant(),scope.path("scope_revision").asText(),intent.release()));requireState(a,intent,registration);return schema.read(saved.receiptJson());
 }
 record State(String status,BigInteger revision,String evaluation,LocalDateTime changed){}
 private static <T>T one(List<T> v){if(v.size()!=1)bad();return v.get(0);}private static void one(int n){if(n!=1)bad();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
